// Upload naming, kinds, and limits for the proxy ingestion write routes (Projects Phase B/C).
//
// TypeScript twins of `agent/src/ingestion/names.py` `sanitize` and `agent/src/ingestion/limits.py`
// (`kind_for`, `limits_from_env`). The proxy derives an upload's object key and asset kind with these,
// and the Asset_Service `register_upload` re-derives both in Python, so they MUST agree byte for byte:
// `ingestionNames.test.ts` runs both over the shared fixture `agent/src/ingestion/fixtures/upload_cases.json`
// (generated by, and asserted against, the Python side in `tests/test_ingestion_remove.py`).
import { projectPrefix } from "./schema";
import type { AssetKind } from "./schema";

/** A sanitized object-key segment is at most 200 characters (design Property 4). */
export const SANITIZE_MAX = 200;

const GIB = 1024 * 1024 * 1024;
const MIB = 1024 * 1024;

/** Per-kind byte limits (contract defaults; `INGESTION_CONFIG.uploadLimits` overrides). */
export const DEFAULT_UPLOAD_LIMITS: Readonly<Record<AssetKind, number>> = Object.freeze({
  video: 5 * GIB,
  audio: 5 * GIB,
  image: 50 * MIB,
  document: 500 * MIB,
});
export const MAX_FILES_PER_BATCH = 20;
/** Files of at least this many bytes upload multipart; smaller ones use one presigned PUT. */
export const MULTIPART_THRESHOLD_BYTES = 100 * MIB;
export const PART_SIZE_BYTES = 64 * MIB;

// Everything outside this class becomes "_" in an object key. The `u` flag iterates code points, as
// Python's `re` does over `str`, so an astral character (an emoji) becomes ONE "_" in both.
const DISALLOWED_KEY_CHAR = /[^A-Za-z0-9._-]/gu;
// A plausible extension for extension-preserving truncation: a dot, then 1-10 of [A-Za-z0-9].
const EXT_RE = /\.[A-Za-z0-9]{1,10}$/;

/** `(stem, ext)` where `ext` includes the leading dot, or `(name, "")` when there is none. */
function splitExt(name: string): [string, string] {
  const m = EXT_RE.exec(name);
  if (!m) return [name, ""];
  return [name.slice(0, m.index), name.slice(m.index)];
}

/**
 * The last segment of a Project object key for `name` — the twin of Python `sanitize`. Contains only
 * `[A-Za-z0-9._-]`, is at most 200 characters, keeps the extension, is idempotent, and is never empty.
 */
export function sanitizeFileName(name: unknown): string {
  const s = typeof name === "string" ? name : "";
  let cleaned = s.replace(DISALLOWED_KEY_CHAR, "_");
  if (!cleaned) cleaned = "_";
  if (cleaned.length <= SANITIZE_MAX) return cleaned;
  const [stem, ext] = splitExt(cleaned);
  if (ext && ext.length < SANITIZE_MAX) return (stem.slice(0, SANITIZE_MAX - ext.length) || "_") + ext;
  return cleaned.slice(0, SANITIZE_MAX);
}

/** `projects/<pid>/<assetId>/<sanitize(fileName)>` — exactly what `register_upload` HEADs. */
export function uploadObjectKey(pid: string, assetId: string, fileName: string): string {
  return `${projectPrefix(pid)}${assetId}/${sanitizeFileName(fileName)}`;
}

// Extension fallback sets: the same as the SPA (`ui/src/projects/upload/kinds.ts`) and Python `limits.py`.
const VIDEO_EXT = new Set(["mp4", "mov", "m4v", "webm", "mkv", "avi", "mpg", "mpeg", "mxf", "ts", "mts", "wmv", "flv", "3gp"]);
const IMAGE_EXT = new Set(["png", "jpg", "jpeg", "gif", "webp", "bmp", "tif", "tiff", "heic", "heif", "avif"]);
const AUDIO_EXT = new Set(["mp3", "wav", "m4a", "aac", "ogg", "oga", "flac", "aif", "aiff", "opus", "wma"]);
const KIND_EXT_RE = /\.([A-Za-z0-9]{1,10})$/;

/** The lower-cased extension (no dot) of the last `/` segment of `name`, or "". */
function extensionOf(name: string): string {
  const base = name.slice(name.lastIndexOf("/") + 1);
  const m = KIND_EXT_RE.exec(base);
  return m ? m[1].toLowerCase() : "";
}

/** The kind of a file: from its content type, else its extension, else `document` (twin of `kind_for`). */
export function kindFor(contentType: unknown, name: unknown): AssetKind {
  const ct = (typeof contentType === "string" ? contentType : "").toLowerCase();
  if (ct.startsWith("video/")) return "video";
  if (ct.startsWith("audio/")) return "audio";
  if (ct.startsWith("image/")) return "image";
  const ext = extensionOf(typeof name === "string" ? name : "");
  if (VIDEO_EXT.has(ext)) return "video";
  if (AUDIO_EXT.has(ext)) return "audio";
  if (IMAGE_EXT.has(ext)) return "image";
  return "document";
}

/** The per-kind limits: defaults overridden by positive integers in `INGESTION_CONFIG.uploadLimits`. */
export function uploadLimitsFromEnv(env: NodeJS.ProcessEnv = process.env): Record<AssetKind, number> {
  const limits: Record<AssetKind, number> = { ...DEFAULT_UPLOAD_LIMITS };
  const raw = env.INGESTION_CONFIG ?? "";
  if (!raw) return limits;
  let cfg: unknown;
  try {
    cfg = JSON.parse(raw);
  } catch {
    return limits;
  }
  const overrides = (cfg as { uploadLimits?: unknown } | null)?.uploadLimits;
  if (overrides && typeof overrides === "object" && !Array.isArray(overrides)) {
    for (const kind of Object.keys(DEFAULT_UPLOAD_LIMITS) as AssetKind[]) {
      const v = (overrides as Record<string, unknown>)[kind];
      if (typeof v === "number" && Number.isSafeInteger(v) && v > 0) limits[kind] = v;
    }
  }
  return limits;
}

/** The `GET …/ingestion/capabilities` body for the configured limits. */
export function ingestionCapabilities(env: NodeJS.ProcessEnv = process.env) {
  return {
    maxFilesPerBatch: MAX_FILES_PER_BATCH,
    limits: uploadLimitsFromEnv(env),
    multipartThresholdBytes: MULTIPART_THRESHOLD_BYTES,
    partSizeBytes: PART_SIZE_BYTES,
  };
}

